-- Title: iam tenant readiness + activate (S11 / EP-01 US-04 + US-05)
-- Kind: patch
-- Intent: iam_tenant_readiness_activate
-- Touches: iam.get_tenant_readiness, iam.activate_tenant, iam.get_auth_user_snapshot
-- Promoted from _drafts/016_iam_tenant_readiness_activate.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.get_auth_user_snapshot(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = iam, auth, pg_temp
as $$
declare
  v_user record;
  v_status text;
begin
  select
    u.id,
    u.email_confirmed_at,
    u.banned_until
  into v_user
  from auth.users u
  where u.id = p_user_id;

  if v_user.id is null then
    return jsonb_build_object(
      'user_id', p_user_id,
      'account_status', 'unavailable',
      'email_verified', false,
      'evaluated_at', now()
    );
  end if;

  if v_user.banned_until is not null and v_user.banned_until > now() then
    v_status := 'suspended';
  else
    v_status := 'active';
  end if;

  return jsonb_build_object(
    'user_id', v_user.id,
    'account_status', v_status,
    'email_verified', v_user.email_confirmed_at is not null,
    'evaluated_at', now()
  );
end;
$$;

-- Only IAM security-definer callers and the service role may execute. Role
-- `authenticated`/`anon`/`public` cannot invoke the Auth snapshot directly.
revoke all on function iam.get_auth_user_snapshot(uuid) from public, anon, authenticated;
grant execute on function iam.get_auth_user_snapshot(uuid) to service_role;

-- ── get_tenant_readiness ──────────────────────────────────────────────────────

create or replace function iam.get_tenant_readiness(p_tenant_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_tenant iam.tenants;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_owner_count int := 0;
  v_legal_exists boolean := false;
  v_duplicate_tax boolean := false;
  v_owner_user uuid;
  v_owner_effective_status text;
  v_owner_tax_code text;
  v_snapshot jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  if not iam.has_permission(p_tenant_id, 'tenant.readiness.view') then
    raise exception 'PERMISSION_DENIED';
  end if;

  select * into v_tenant from iam.tenants t where t.id = p_tenant_id;
  if not found then
    raise exception 'RESOURCE_NOT_FOUND';
  end if;

  if coalesce(v_tenant.display_name, '') = '' then
    v_blockers := v_blockers || to_jsonb('TENANT_DISPLAY_NAME_MISSING'::text);
  end if;
  if coalesce(v_tenant.contact_email, '') = '' then
    v_blockers := v_blockers || to_jsonb('TENANT_CONTACT_EMAIL_MISSING_OR_INVALID'::text);
  end if;
  if coalesce(v_tenant.contact_phone, '') = '' then
    v_blockers := v_blockers || to_jsonb('TENANT_CONTACT_PHONE_MISSING_OR_INVALID'::text);
  end if;
  if coalesce(v_tenant.contact_address_text, '') = '' then
    v_blockers := v_blockers || to_jsonb('TENANT_CONTACT_ADDRESS_MISSING'::text);
  end if;

  select count(*) into v_owner_count
  from iam.memberships m
  where m.tenant_id = p_tenant_id
    and m.is_owner is true
    and m.is_active;

  if v_owner_count <> 1 then
    if v_owner_count = 0 and v_tenant.status = 'provisioning' then
      if exists (
        select 1 from iam.tenant_invitations i
        where i.tenant_id = p_tenant_id
          and i.is_owner is true
          and i.status = 'pending'
          and i.expires_at > now()
      ) then
        v_blockers := v_blockers || to_jsonb('OWNER_ACCEPTANCE_PENDING'::text);
      else
        v_blockers := v_blockers || to_jsonb('OWNER_INVITATION_EXPIRED'::text);
      end if;
    else
      v_blockers := v_blockers || to_jsonb('OWNER_MEMBERSHIP_INVALID'::text);
    end if;
  else
    -- Owner identity readiness: Auth-confirmed identity + verified email.
    select m.user_id into v_owner_user
    from iam.memberships m
    where m.tenant_id = p_tenant_id
      and m.is_owner is true
      and m.is_active
    limit 1;

    select iam._platform_user_effective_status(u.email_confirmed_at)
    into v_owner_effective_status
    from auth.users u
    where u.id = v_owner_user;

    if coalesce(v_owner_effective_status, '') <> 'active' then
      v_blockers := v_blockers || to_jsonb('OWNER_IDENTITY_INACTIVE'::text);
    end if;

    -- Auth snapshot is authoritative for email verification.
    v_snapshot := iam.get_auth_user_snapshot(v_owner_user);
    if v_snapshot ->> 'account_status' = 'unavailable' then
      v_blockers := v_blockers || to_jsonb('OWNER_IDENTITY_UNAVAILABLE'::text);
    elsif coalesce((v_snapshot ->> 'email_verified')::boolean, false) is not true then
      v_blockers := v_blockers || to_jsonb('OWNER_EMAIL_UNVERIFIED'::text);
    end if;
  end if;

  select exists (
    select 1 from iam.tenant_legal_profiles lp where lp.tenant_id = p_tenant_id
  ) into v_legal_exists;

  if not v_legal_exists then
    -- Missing Legal Profile is a warning, never a blocker (locked contract).
    v_warnings := v_warnings || to_jsonb('LEGAL_PROFILE_MISSING'::text);
  else
    -- Duplicate tax code is a warning, never a blocker (locked contract).
    select lp.tax_code into v_owner_tax_code
    from iam.tenant_legal_profiles lp
    where lp.tenant_id = p_tenant_id;

    select exists (
      select 1 from iam.tenant_legal_profiles lp2
      where lp2.tax_code = v_owner_tax_code
        and lp2.tenant_id <> p_tenant_id
    ) into v_duplicate_tax;

    if v_duplicate_tax then
      v_warnings := v_warnings || to_jsonb('DUPLICATE_TAX_CODE'::text);
    end if;
  end if;

  return jsonb_build_object(
    'tenant_id', p_tenant_id,
    'status', v_tenant.status,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'evaluated_at', now(),
    'tenant_version', v_tenant.version,
    'can_activate', jsonb_array_length(v_blockers) = 0
      and v_tenant.status = 'provisioning'
  );
end;
$$;

-- ── activate_tenant ─────────────────────────────────────────────────────────

create or replace function iam.activate_tenant(
  p_tenant_id uuid,
  p_expected_version int,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_tenant iam.tenants;
  v_existing iam.idempotency_records;
  v_readiness jsonb;
  v_blockers jsonb;
  v_payload_hash text := md5(p_expected_version::text);
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  if not iam.has_permission(p_tenant_id, 'tenant.activate') then
    raise exception 'PERMISSION_DENIED';
  end if;

  select * into v_existing
  from iam.tenant_activation_operations o
  where o.tenant_id = p_tenant_id
    and o.idempotency_key = p_idempotency_key;

  if found then
    -- Same key + same payload -> replay same result; different payload -> conflict.
    if v_existing.payload_hash <> v_payload_hash then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.result;
  end if;

  -- Lock Tenant and its active Owner Membership before re-evaluating readiness.
  select * into v_tenant from iam.tenants t where t.id = p_tenant_id for update;
  if not found then
    raise exception 'RESOURCE_NOT_FOUND';
  end if;

  perform 1
  from iam.memberships m
  where m.tenant_id = p_tenant_id
    and m.is_owner is true
    and m.is_active
  for update;

  if v_tenant.status <> 'provisioning' then
    raise exception 'TENANT_STATE_INVALID';
  end if;

  if v_tenant.version <> p_expected_version then
    raise exception 'STATE_CHANGED';
  end if;

  -- Re-evaluate the full readiness inside the transaction; stale UI cannot skip.
  v_readiness := iam.get_tenant_readiness(p_tenant_id);
  v_blockers := v_readiness -> 'blockers';
  if jsonb_array_length(v_blockers) > 0 then
    raise exception 'READINESS_BLOCKED';
  end if;

  update iam.tenants
  set
    status = 'active',
    activated_at = now(),
    status_changed_at = now(),
    version = v_tenant.version + 1,
    updated_at = now()
  where id = p_tenant_id
  returning * into v_tenant;

  v_result := jsonb_build_object(
    'tenant_id', v_tenant.id,
    'status', v_tenant.status,
    'activated_at', v_tenant.activated_at,
    'version', v_tenant.version
  );

  insert into iam.tenant_activation_operations (
    tenant_id,
    idempotency_key,
    payload_hash,
    result
  )
  values (
    p_tenant_id,
    p_idempotency_key,
    v_payload_hash,
    v_result
  );

  -- Domain change + audit row in the same transaction. Audit failure must
  -- roll back activation, so this is NOT wrapped in an exception handler.
  perform iam.append_audit_log(
    p_scope => 'tenant',
    p_tenant_id => p_tenant_id,
    p_actor_user_id => auth.uid(),
    p_event_code => 'iam.tenant.activated',
    p_subject_type => 'tenant',
    p_subject_id => v_tenant.id::text,
    p_result => 'success',
    p_source => 'iam',
    p_tracking_id => p_idempotency_key,
    p_before => jsonb_build_object('status', 'provisioning', 'version', p_expected_version),
    p_after => jsonb_build_object('status', v_tenant.status, 'version', v_tenant.version)
  );

  -- Domain change + integration event in the same transaction (outbox pattern).
  perform iam.enqueue_outbox_message(
    p_tenant_id,
    'iam.tenant.activated',
    jsonb_build_object(
      'tenant_id', v_tenant.id,
      'version', v_tenant.version,
      'activated_at', v_tenant.activated_at
    )
  );

  return v_result;
end;
$$;
